#!/usr/bin/env python3
"""Regenerate diagrams/bundle.js from diagrams/*.mmd + manifest.json.
The page fetches the .mmd files over HTTP; bundle.js is the fallback for file://.
Run after editing any .mmd:  python3 build-bundle.py
"""
import json, pathlib
root = pathlib.Path(__file__).resolve().parent / 'diagrams'
manifest = json.loads((root / 'manifest.json').read_text('utf8'))
for m in manifest:
    m['file'] = f"diagrams/{m['id']}.mmd"
    m['source'] = (root / f"{m['id']}.mmd").read_text('utf8')
(root / 'bundle.js').write_text(
    '// generated by build-bundle.py — do not edit; edit the .mmd files instead\n'
    'window.TWEAKPELE_DIAGRAMS = ' + json.dumps(manifest, ensure_ascii=False, indent=1) + ';\n', 'utf8')
print(f'bundled {len(manifest)} diagrams')
